parts={ 'ESP.5V':'K2','ESP.IO13':'K6','ESP.GND':'K7','ESP.IO27':'K10','ESP.IO26':'K11','ESP.IO25':'K12','ESP.IO32':'K14',
 'J1.+5V':'W2','J1.GND':'W4','J2.IN1':'W6','J2.IN2':'W8','J3.SW':'W11','J3.GND':'W13','J4.AZUL':'W16','J4.VERDE':'W18','J4.GRIS':'W20',
 'R1.a':'V18','R1.b':'R18','D1.A':'Q18','D1.K':'Q22','U1.1':'P20','U1.2':'P19','U1.3':'P18','U1.4':'M18','U1.5':'M19','U1.6':'M20',
 'C1.-':'M12','C1.+':'N12','R2.a':'O12','R2.b':'S12'}
wires={'5V':['K2','W2'],'IN1':['K6','W6'],'GNDa':['K7','X7'],'BUS':['X4','X20'],'b1':['W4','X4'],'b2':['W13','X13'],'b3':['W20','X20'],
 'IN2':['K10','V10','V8','W8'],'SW':['K11','W11'],'DAC':['K12','M12'],'b4':['N12','O12'],'AZ':['S12','U12','U16','W16'],
 'b5':['V18','W18'],'b6':['Q18','R18'],'D1K':['Q22','P22','P20'],'b7':['P18','P19'],'EMI':['M18','P18'],'GR':['P19','S19','S20','V20'],'b8':['V20','W20'],'DET':['M19','L19','L14'],'b9':['L14','K14']}
par={}
def f(x):
  par.setdefault(x,x)
  while par[x]!=x: x=par[x]
  return x
def u(a,b): par[f(a)]=f(b)
pts={}
for n,w in wires.items():
  cells=[]
  for a,b in zip(w,w[1:]):
    (c1,r1),(c2,r2)=p(a),p(b)
    assert c1==c2 or r1==r2,(n,a,b)
    if c1==c2:
      s=1 if r2>r1 else -1
      cells+=[C[c1]+str(r) for r in range(r1,r2+s,s)]
    else:
      s=1 if c2>c1 else -1
      cells+=[C[c]+str(r1) for c in range(c1,c2+s,s)]
  for a in w: u(n,'h'+a)
  pts[n]=(w[0],w[-1],set(cells))
hole2part={v:k for k,v in parts.items()}
nets={}
for k,v in parts.items(): nets.setdefault(f('h'+v),[]).append(k)
for k,v in sorted(nets.items(),key=lambda x:x[1]): print(v)
# conflicts
err=0
for n,(a,b,cells) in pts.items():
  for c in cells-{a,b}:
    if c in hole2part: print('wire',n,'passes over pad',c,hole2part[c]); err+=1
names=list(pts)
for i in range(len(names)):
  for j in range(i+1,len(names)):
    A,B=names[i],names[j]
    if f(A)!=f(B):
      s=pts[A][2]&pts[B][2]
      if s: print('CROSS',A,B,s); err+=1
print('errors',err)
