const parts=[
 {id:'ESP32',desc:'ESP32 DevKit 38 pines en tiras hembra, USB arriba',pins:Object.fromEntries([...pinsR.map((n,i)=>['K'+(i+2),'R:'+n]),...pinsL.map((n,i)=>['A'+(i+2),'L:'+n])])},
 {id:'J1',desc:'Borna 2 polos: alimentación del módulo de relés',pins:{W2:'+5V → DC+',W4:'GND → DC−'}},
 {id:'J2',desc:'Borna 2 polos: señales del módulo de relés',pins:{W6:'IN1',W8:'IN2'}},
 {id:'J3',desc:'Borna 2 polos: interruptor de modo',pins:{W11:'IO26',W13:'GND'}},
 {id:'J4',desc:'Borna 3 polos: portero',pins:{W16:'azul',W18:'verde (calle)',W20:'gris'}},
 {id:'R1',desc:'1 kΩ (marrón-negro-rojo)',pins:{V18:'lado verde',R18:'lado D1'}},
 {id:'D1',desc:'1N4007: la banda (cátodo) ABAJO, en Q22',pins:{Q18:'ánodo',Q22:'cátodo (banda)'}},
 {id:'U1',desc:'4N35: muesca HACIA ABAJO; pin 1 abajo a la derecha (P20)',pins:{P20:'1 ánodo LED',P19:'2 cátodo LED',P18:'3 sin conexión',M18:'4 emisor',M19:'5 colector',M20:'6 base (libre)'}},
 {id:'C1',desc:'10 µF ≥25 V electrolítico: el − (franja) en M12, el + en N12',pins:{M12:'− (franja)',N12:'+'}},
 {id:'R2',desc:'47 kΩ (amarillo-violeta-naranja), en zócalo: suelda en O12 y S12 un pin suelto de tira hembra y pincha ahí la resistencia, para cambiarla al probar (22 k / 47 k / 100 k)',pins:{O12:'lado C1',S12:'lado azul'}},
 {id:'R3',desc:'100 kΩ (marrón-negro-amarillo), vertical: lleva a masa el lado ESP de C1',pins:{M13:'lado C1−',M17:'lado GND'}},
];
const wires=[
 {id:'w1',net:'+5V',path:['K2','W2'],t:'cable'},
 {id:'w2',net:'IN1',path:['K6','W6'],t:'cable'},
 {id:'w3',net:'GND',path:['K7','X7'],t:'cable'},
 {id:'w4',net:'GND',path:['X4','X20'],t:'bus',note:'Bus de masa: cable desnudo soldado en cada agujero de X4 a X20'},
 {id:'b1',net:'GND',path:['W4','X4'],t:'puente'},
 {id:'b2',net:'GND',path:['W13','X13'],t:'puente'},
 {id:'b3',net:'GND',path:['W20','X20'],t:'puente'},
 {id:'w5',net:'IN2',path:['K10','V10','V8','W8'],t:'cable'},
 {id:'w6',net:'SW',path:['K11','W11'],t:'cable'},
 {id:'w7',net:'DAC',path:['K12','M12'],t:'cable'},
 {id:'b4',net:'C1-R2',path:['N12','O12'],t:'puente'},
 {id:'w8',net:'AZUL',path:['S12','U12','U16','W16'],t:'cable'},
 {id:'b5',net:'VERDE',path:['V18','W18'],t:'puente'},
 {id:'b6',net:'R1-D1',path:['Q18','R18'],t:'puente'},
 {id:'w9',net:'D1-LED',path:['Q22','P22','P20'],t:'cable'},
 {id:'b7',net:'GND',path:['P18','P19'],t:'puente',note:'El pin 3 no tiene conexión interna: se usa como punto de unión'},
 {id:'w10',net:'GND',path:['M18','P18'],t:'cable',note:'Pasa por debajo del 4N35'},
 {id:'w11',net:'GND',path:['P19','S19','S20','V20'],t:'cable'},
 {id:'b8',net:'GND',path:['V20','W20'],t:'puente'},
 {id:'w12',net:'DET',path:['M19','L19','L14'],t:'cable'},
 {id:'b9',net:'DET',path:['L14','K14'],t:'puente'},
 {id:'b10',net:'DAC',path:['M12','M13'],t:'puente'},
 {id:'b11',net:'GND',path:['M17','M18'],t:'puente',note:'R3 a masa por el emisor de U1 (M18 es GND)'},
];
const expected={'+5V':['ESP32.K2','J1.W2'],'GND':['ESP32.K7','J1.W4','J3.W13','J4.W20','U1.M18','U1.P19','U1.P18','R3.M17'],'IN1':['ESP32.K6','J2.W6'],'IN2':['ESP32.K10','J2.W8'],'SW':['ESP32.K11','J3.W11'],'DAC':['ESP32.K12','C1.M12','R3.M13'],'C1-R2':['C1.N12','R2.O12'],'AZUL':['R2.S12','J4.W16'],'VERDE':['J4.W18','R1.V18'],'R1-D1':['R1.R18','D1.Q18'],'D1-LED':['D1.Q22','U1.P20'],'DET':['U1.M19','ESP32.K14']};
const hp=h=>[COLS.indexOf(h[0]),+h.slice(1)];
function cells(path){const out=[];for(let i=0;i<path.length-1;i++){const[c1,r1]=hp(path[i]),[c2,r2]=hp(path[i+1]);if(c1===c2){const s=r2>r1?1:-1;for(let r=r1;r!==r2+s;r+=s)out.push(COLS[c1]+r);}else{const s=c2>c1?1:-1;for(let c=c1;c!==c2+s;c+=s)out.push(COLS[c]+r1);}}return[...new Set(out)];}
function validate(){
  const par={};const f=x=>{par[x]??=x;while(par[x]!==x)x=par[x];return x};const u=(a,b)=>par[f(a)]=f(b);
  const hole2pin={};parts.forEach(p=>Object.keys(p.pins).forEach(h=>hole2pin[h]=p.id+'.'+h));
  const errs=[];
  wires.forEach(w=>{const cs=cells(w.path);const conn=w.t==='bus'||w.t==='puente'?cs:w.path;conn.forEach(h=>u(w.id,'h'+h));
    if(w.t==='cable')cs.filter(h=>!w.path.includes(h)).forEach(h=>{if(hole2pin[h])errs.push(`${w.id} pasa por encima del pin ${hole2pin[h]}`)});});
  // crossings: shared hole between wires of different nets
  for(let i=0;i<wires.length;i++)for(let j=i+1;j<wires.length;j++){const A=wires[i],B=wires[j];if(f(A.id)===f(B.id))continue;const ca=cells(A.path),cb=new Set(cells(B.path));ca.forEach(h=>{if(cb.has(h))errs.push(`Cruce: ${A.id} y ${B.id} en ${h}`)})}
  // nets compare
  const nets={};Object.entries(hole2pin).forEach(([h,p])=>{if(par['h'+h]===undefined)return;(nets[f('h'+h)]??=[]).push(p)});
  const got=Object.values(nets).filter(n=>n.length>1).map(n=>n.sort().join(' · ')).sort();
  const exp=Object.values(expected).map(n=>[...n].sort().join(' · ')).sort();
  exp.forEach(n=>{if(!got.includes(n))errs.push('Falta la conexión: '+n)});
  got.forEach(n=>{if(!exp.includes(n))errs.push('Conexión de más: '+n)});
  return{errs,got};
}
let mirror=false;
function drawPlaca(){
  const P=24,ox=46,oy=40,nC=24,nR=30,Wd=ox*2+P*(nC-1),Hd=oy+P*(nR-1)+40;
  const X=c=>ox+P*(mirror?nC-1-c:c),Y=r=>oy+P*(r-1),pt=h=>{const[c,r]=hp(h);return[X(c),Y(r)]};
  let s=`<rect x="${ox-20}" y="${oy-22}" width="${P*(nC-1)+40}" height="${P*(nR-1)+44}" rx="8" style="fill:var(--board);stroke:var(--line)"/>`;
  for(let c=0;c<nC;c++){s+=`<text class="lbls" x="${X(c)}" y="${oy-28}" text-anchor="middle" style="font-weight:700">${COLS[c]}</text>`;}
  for(let r=1;r<=nR;r++){s+=`<text class="lbls" x="${mirror?Wd-12:12}" y="${Y(r)+4}" text-anchor="middle">${r}</text>`;}
  for(let c=0;c<nC;c++)for(let r=1;r<=nR;r++)s+=`<circle cx="${X(c)}" cy="${Y(r)}" r="3.2" style="fill:var(--hole)"/>`;
  const top=!mirror,op=top?1:.28;
  // part bodies
  const box=(a,b,lab,fill)=>{const[x1,y1]=pt(a),[x2,y2]=pt(b);const x=Math.min(x1,x2)-11,y=Math.min(y1,y2)-11,w=Math.abs(x2-x1)+22,h=Math.abs(y2-y1)+22;return`<g opacity="${op}"><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="5" style="fill:${fill};stroke:var(--ink);stroke-width:1.2"/><text class="lbl" x="${x+w/2}" y="${y+h/2+4}" text-anchor="middle" style="font-weight:700">${lab}</text></g>`};
  s+=`<g opacity="${op}"><rect x="${Math.min(X(0),X(10))-14}" y="${Y(1)-30}" width="${Math.abs(X(10)-X(0))+28}" height="${Y(21)-Y(1)+40}" rx="6" style="fill:#23465f;opacity:.18;stroke:var(--ink)"/><text class="lblb" x="${(X(0)+X(10))/2}" y="${Y(11)}" text-anchor="middle">ESP32</text><text class="lbls" x="${(X(0)+X(10))/2}" y="${Y(11)+18}" text-anchor="middle">tiras hembra en A y K</text><rect x="${(X(0)+X(10))/2-16}" y="${Y(1)-44}" width="32" height="22" rx="3" style="fill:var(--mute)"/><text class="lbls" x="${(X(0)+X(10))/2}" y="${Y(1)-50}" text-anchor="middle">USB ↑</text></g>`;
  s+=box('W2','X4','J1','#4f83c6')+box('W6','X8','J2','#4f83c6')+box('W11','X13','J3','#4f83c6')+box('W16','X20','J4','#4f83c6');
  s+=box('S18','U18','R1','#d8b48a')+box('Q19','Q21','D1','#555')+box('N18','O20','U1','#333')+box('P12','R12','R2','#d8b48a')+box('M14','M16','R3','#d8b48a');
  {const[a,b]=pt('M12'),[c]=pt('N12');s+=`<g opacity="${op}"><circle cx="${(a+c)/2}" cy="${b}" r="15" style="fill:#3b5ea8;stroke:var(--ink)"/><text class="lbl" x="${(a+c)/2}" y="${b+4}" text-anchor="middle" style="fill:#fff;font-weight:700">C1</text></g>`;}
  {const[x,y]=pt('Q22');s+=`<rect opacity="${op}" x="${x-8}" y="${y-18}" width="16" height="5" style="fill:#ddd"/>`;const[ux,uy]=pt('N20');s+=`<path opacity="${op}" d="M${(ux+pt('O20')[0])/2-7} ${uy+11}a7 7 0 0 0 14 0" style="fill:var(--bg)"/>`;}
  {const y=(Y(28)+Y(29))/2;s+=`<path d="M${ox-24} ${y}H${ox+P*(nC-1)+24}" style="stroke:var(--bad);stroke-width:2.5;stroke-dasharray:8 5"/><text class="vb" x="${X(12)}" y="${y+16}" text-anchor="middle" style="fill:var(--bad);font-size:11px">✂ cortar aquí (por la fila 29)</text>`;
   ['A26','X26'].forEach(h=>{const[x,yy]=pt(h);s+=`<circle cx="${x}" cy="${yy}" r="9" style="fill:var(--bg);stroke:var(--bad);stroke-width:2.5"><title>${h}: taladro M3 nuevo (3,2 mm)</title></circle><text class="vb" x="${x}" y="${yy+22}" text-anchor="middle" style="fill:var(--bad);font-size:10px">M3</text>`;});}
  // wires (solder side): draw always, faded on top view
  const wop=top?.75:1;
  wires.forEach(w=>{const d='M'+w.path.map(pt).map(p=>p.join(' ')).join('L');const col=NETC[w.net];
    if(w.t==='cable')s+=`<path d="${d}" style="fill:none;stroke:${col};stroke-width:5;stroke-linecap:round;stroke-linejoin:round;opacity:${wop}"><title>${w.id} · ${w.net}</title></path>`;
    else s+=`<path d="${d}" style="fill:none;stroke:#b8bcc4;stroke-width:${w.t==='bus'?6:7};stroke-linecap:round;opacity:${wop}"/><path d="${d}" style="fill:none;stroke:${col};stroke-width:2;stroke-dasharray:${w.t==='bus'?'0':'3 3'};opacity:${wop}"><title>${w.id} · ${w.net}</title></path>`;});
  // pads used
  parts.forEach(p=>Object.entries(p.pins).forEach(([h,lab])=>{const[x,y]=pt(h);const used=wires.some(w=>cells(w.path).includes(h)&&(w.path.includes(h)||w.t!=='cable'));
    s+=`<circle cx="${x}" cy="${y}" r="${used?6:4.5}" style="fill:var(--pad);stroke:${used?'var(--ink)':'none'};stroke-width:1.2"><title>${h} · ${p.id} ${lab}</title></circle>`;}));
  // ESP pin labels on right header
  pinsR.forEach((n,i)=>{const[x,y]=pt('K'+(i+2));const dx=mirror?14:-14;s+=`<text class="lbls" x="${x+dx}" y="${y+4}" text-anchor="${mirror?'start':'end'}" style="font-size:10px;font-family:'JetBrains Mono';paint-order:stroke;stroke:var(--board);stroke-width:4px;${['5V','IO13','GND','IO27','IO26','IO25','IO32'].includes(n)?'fill:var(--ink);font-weight:600':''}">${n}</text>`});
  // terminal labels
  [['W2','+5V'],['W4','GND'],['W6','IN1'],['W8','IN2'],['W11','IO26'],['W13','GND'],['W16','AZUL'],['W18','VERDE'],['W20','GRIS']].forEach(([h,t])=>{const[x,y]=pt(h);s+=`<text class="vb" x="${mirror?x-40:x+40}" y="${y+4}" text-anchor="${mirror?'end':'start'}" style="fill:var(--ink);font-size:11px">${t}</text>`});
  const Wtot=Wd+70;const svg=$('#svgPlaca');svg.setAttribute('viewBox',`${mirror?-70:0} -40 ${Wtot} ${Hd+50}`);svg.innerHTML=s;
  $('#placaView').textContent=mirror?'Vista: soldadura (placa girada, columna A a la DERECHA)':'Vista: componentes (arriba). Cables de abajo vistos por transparencia';
}
document.querySelector('[data-act=mirror]').onclick=()=>{mirror=!mirror;drawPlaca();};
drawPlaca();
(function(){const{errs,got}=validate();
  $('#placaCheck').innerHTML=errs.length?`<div class="note"><b>Validación con errores:</b><br>${errs.join('<br>')}</div>`:`<div class="okbox"><b>Validación automática correcta.</b> Las ${got.length} conexiones de la placa, calculadas a partir de los cables y puentes dibujados, coinciden con el esquema. 0 cruces. Ningún cable pasa por encima de un pin ajeno.</div>`;
  $('#tblParts').innerHTML='<tr><th>Pieza</th><th>Montaje</th><th>Agujeros</th></tr>'+parts.filter(p=>p.id!=='ESP32').map(p=>`<tr><td><b>${p.id}</b></td><td>${p.desc}</td><td class="mono">${Object.entries(p.pins).map(([h,l])=>h+' '+l).join('<br>')}</td></tr>`).join('')+`<tr><td><b>ESP32</b></td><td>Tiras hembra en la columna A (filas 2–20) y en la K (filas 2–20). Si tu ESP tiene 9 agujeros entre filas, la izquierda va en B; la derecha sigue en K</td><td class="mono">K2 5V · K6 IO13 · K7 GND · K10 IO27 · K11 IO26 · K12 IO25 · K14 IO32</td></tr>`;
  $('#tblWires').innerHTML='<tr><th>#</th><th>Tipo</th><th>Recorrido</th><th>Señal</th><th>Nota</th></tr>'+wires.map(w=>`<tr><td class="mono">${w.id}</td><td>${w.t==='cable'?'cable aislado':w.t==='bus'?'cable desnudo (bus)':'puente de estaño'}</td><td class="mono">${w.path.join(' → ')}</td><td><span class="sw" style="background:${NETC[w.net]}"></span>${w.net}</td><td>${w.note||''}</td></tr>`).join('');
})();

