import heapq, itertools, json, sys, random
COLS='ZYXWVUTSRQPONMLKJIHGFEDCBA'
NC,NR=26,31
def h(c,r): return COLS[c]+str(r)
def p(s): return (COLS.index(s[0]), int(s[1:]))
CI=lambda L: COLS.index(L)
RP=['5V','CMD','D3','D2','IO13','GND','IO12','IO14','IO27','IO26','IO25','IO33','IO32','IO35','IO34','VN','VP','EN','3V3']
LP=['CLK','D0','D1','IO15','IO2','IO0','IO4','IO16','IO17','IO5','IO18','IO19','GND','IO21','RX','TX','IO22','IO23','GND']
def base():
    pads={}
    for i,n in enumerate(RP): pads[h(CI('C'),13+i)]='ESP:R:'+n
    for i,n in enumerate(LP): pads[h(CI('M'),13+i)]='ESP:L:'+n
    term={'X2':'J5a','V2':'J5b','S2':'J4v','Q2':'J4a','N2':'J3g','L2':'J3s','F2':'J1i2','D2':'J1i1','B2':'J1p'}
    for k,v in term.items(): pads[k]=v
    pads['Q4']='R2az'; pads['P11']='C1m'
    forbid=set()
    for c in range(NC):
        forbid.add(h(c,1))
        if h(c,2) not in pads: forbid.add(h(c,2))
        if c not in [p(t)[0] for t in term]: forbid.add(h(c,3))
    for L in 'RQP':
        for r in range(5,11): forbid.add(L+str(r))
    return pads,forbid,term
def route(pads,forbid,nets,order,netpads):
    occ={k:('pad',v) for k,v in pads.items()}
    out={};total=0
    for net in order:
        a,b=netpads[net]
        # dijkstra a->b; may enter cell if free or is b
        dist={a:0};pq=[(0,a,None)];prev={}
        found=False
        while pq:
            d,u,dr=heapq.heappop(pq)
            if d>dist.get(u,1e9): continue
            if u==b: found=True;break
            cu,ru=p(u)
            for dc,drr in((1,0),(-1,0),(0,1),(0,-1)):
                cv,rv=cu+dc,ru+drr
                if not(0<=cv<NC and 1<=rv<=NR): continue
                v=h(cv,rv)
                if v!=b:
                    if v in forbid: 
                        # row3 under own terminal allowed
                        if not (rv==3 and (h(cv,2)==b or h(cv,2)==a)): continue
                    if v in occ: continue
                turn=0 if dr in (None,(dc,drr)) else 0.5
                nd=d+1+turn
                if nd<dist.get(v,1e9): dist[v]=nd;prev[v]=(u,(dc,drr));heapq.heappush(pq,(nd,v,(dc,drr)))
        if not found: return None,net
        path=[b];x=b
        while x!=a: x=prev[x][0];path.append(x)
        path.reverse()
