import random, itertools, json
random.seed(11)
pads0,forbid0,term=base()
fixed={'+5V':['C13','C4','B4','B2'],'IN1':['C17','D17','D2'],'GND-1':['C18','F18','F2'],'IN2':['C21','I21','I4','L4','L2'],'SW':['C22','J22','J5','N5','N2']}
def expand(path):
    out=[]
    for a,b in zip(path,path[1:]):
        (c1,r1),(c2,r2)=p(a),p(b)
        if c1==c2:
            st=1 if r2>r1 else -1
            out+= [h(c1,r) for r in range(r1,r2+st,st)]
        else:
            st=1 if c2>c1 else -1
            out+= [h(c,r1) for c in range(c1,c2+st,st)]
    return list(dict.fromkeys(out))
zone=set(L+str(r) for L in 'RQPO' for r in range(4,13))
nets=['AZUL','DAC','DET','VERDE','GRIS','GND-U1','GND-J5']
def setup(u,r,mode,g):
    pads=dict(pads0);forbid=set(forbid0)
    for n,pp in fixed.items():
        for x in expand(pp)[1:-1]: forbid.add(x)
    cell=lambda dc,dr: h(u+dc,r+dr)
    if not(0<=u-4 and u+3<NC and r-4>=4 and r+2<=NR): return None
    U={'U1':cell(0,0),'U2':cell(0,1),'U3':cell(0,2),'U6':cell(3,0),'U5':cell(3,1),'U4':cell(3,2)}
    ch={'R1a':cell(-4,0),'R1b':cell(-3,0),'D1a':cell(-2,0),'D1k':cell(-1,0)} if mode=='L' else {'R1a':cell(0,-4),'R1b':cell(0,-3),'D1a':cell(0,-2),'D1k':cell(0,-1)}
    chain={**ch,**U}
    body=[cell(dc,dr) for dc in (1,2) for dr in (0,1,2)]
    for v in list(chain.values())+body:
        c,rr=p(v)
        if v in pads or v in forbid: return None
        if CI('M')<=c<=CI('C') and rr>=11: return None
        if CI('N')<=c and rr<=12: return None   # keep top-right area for wires
        if rr<5: return None
        for z in zone:
            zc,zr=p(z)
            if max(abs(zc-c),abs(zr-rr))<2: return None
    for k,v in chain.items(): pads[v]=k
    forbid|=set(body)
    for L in 'RQP':
        for rr in range(5,11): forbid.add(L+str(rr))
    netpads={'DAC':('C23','P11'),'DET':('C25',chain['U5']),'AZUL':('Q2','Q4'),'VERDE':('S2',chain['R1a']),'GRIS':('V2',chain['U2']),
             'GND-U1':(g[0],chain['U4']),'GND-J5':(g[1],'X2')}
    return pads,forbid,netpads,chain
best=None
for u in range(0,13):
  for r in range(5,29):
