            # penalize DAC end neighbours touched by other wires
            bad=0
            near={h(p('P11')[0]+dc,11+dr) for dc in (-1,0,1) for dr in (-1,0,1)}
            for n,pp in res.items():
                if n!='DAC' and set(pp)&near: bad+=1
            bends=sum(len(simplify(pp))-2 for pp in res.values())
            sc=tot+2*bends+30*bad
            if best is None or sc<best[0]:
                best=(sc,res,chain,netpads,(u,r,mode,g));print(round(sc,1),u,r,mode,g,bad,flush=True)
            break
sc,res,chain,netpads,meta=best
json.dump({'res':{k:simplify(v) for k,v in res.items()},'chain':chain,'meta':meta},open('best3.json','w'),indent=1)
EOF
