term('mod.IN2',1240,460,'R');term('mod.IN1',1240,500,'R');term('mod.DCN',1240,640,'R');term('mod.DCP',1240,680,'R')
box('cer',1180,860,1760,1110)
CX={'1a':1210,'1b':1230,'2':1280,'3':1350,'4':1400,'5a':1460,'5b':1480,'6':1520,'7':1630,'8':1680,'9':1730}
for k,x in CX.items(): term('cer.'+k,x,860,'U')
box('int',1440,640,1560,710); term('int.A',1480,710,'D'); term('int.B',1520,710,'D')
box('wagoP',1440,180,1540,260); box('wagoN',1600,180,1700,260)
