    w('teg.'+n,'mod.NC2' if c=='verde' else 'bar.'+c.upper(),c)
for n,c,x in VE:
    w('veo.'+n,'mod.NC1' if c=='verde' else 'bar.'+c.upper(),c)
w('bar.AZUL','cer.4','azul'); w('bar.GRIS','cer.1a','gris'); w('cer.1b','cer.2','gris')
w('mod.COM1.b','mod.COM2.a','verde'); w('mod.COM2.b','cer.3','verde')
w('mod.IN2','cer.7','sig'); w('mod.IN1','cer.8','sig')
w('wP.o1','mod.DCP','v5'); w('wP.o2','cer.9','v5'); w('wN.o1','mod.DCN','gnd'); w('wN.o2','cer.5a','gnd')
w('int.A','cer.5b','int'); w('int.B','cer.6','int')
fixed=[([(180,70),(260,70)],'red'),([(420,60),(560,60)],'v5'),([(420,90),(560,90)],'gnd'),
       ([(660,60),(1480,60),(1480,180)],'v5'),([(660,90),(1640,90),(1640,180)],'gnd')]
for k,y in bars.items(): fixed.append(([(BX0,y),(BX1,y)],'BAR:'+k))
D={'L':(-1,0),'R':(1,0),'U':(0,-1),'D':(0,1)}
DIRS=[(1,0),(-1,0),(0,1),(0,-1)]
cell=lambda x,y:(x//G,y//G)
blocked=set()
for n,(x0,y0,x1,y1) in boxes.items():
    for gx in range(x0//G-1,x1//G+2):
        for gy in range(y0//G-1,y1//G+2): blocked.add((gx,gy))
def segcells(pts):
    cells=[]
    for (x1,y1),(x2,y2) in zip(pts,pts[1:]):
        a,b=cell(x1,y1),cell(x2,y2)
        if a[0]==b[0]: st=1 if b[1]>a[1] else -1; seg=[(a[0],y) for y in range(a[1],b[1]+st,st)]
        else: st=1 if b[0]>a[0] else -1; seg=[(x,a[1]) for x in range(a[0],b[0]+st,st)]
        cells+= seg if not cells else seg[1:]
    return cells
def run(order):
    occ={}
    def mark(path,wid,ends=True):
        for i,c in enumerate(path):
            if ends and (i==0 or i==len(path)-1): t='E'
            else:
                a=path[i-1] if i>0 else path[i+1]; b=path[i+1] if i<len(path)-1 else path[i-1]
                t='V' if a[0]==b[0] else ('H' if a[1]==b[1] else 'C')
            occ.setdefault(c,[]).append((wid,t))
    for k,(pts,c) in enumerate(fixed): mark(segcells(pts),'F%d'%k,ends=not c.startswith('BAR'))
    barcells={k:set(segcells([(BX0,y),(BX1,y)])) for k,y in bars.items()}
    res={};total=0
    for wid in order:
        a,b,col=wires[wid]
        ax,ay,ad=terms[a]; s=cell(ax,ay); sd=D[ad]; s1=(s[0]+sd[0],s[1]+sd[1])
        if b.startswith('bar.'):
            bk=b[4:]; targets={}
            for c in barcells[bk]:
                L=occ.get(c,[])
                if len(L)!=1: continue  # already tapped (would have 2 entries)
                for dd in [(0,1),(0,-1),(1,0),(-1,0)]:
                    pre=(c[0]-dd[0],c[1]-dd[1])
                    if dd[1]==0 and c not in [cell(BX0,bars[bk]),cell(BX1,bars[bk])]: continue
                    if dd[1]==0:
                        if (dd[0]==1 and c!=cell(BX0,bars[bk])) or (dd[0]==-1 and c!=cell(BX1,bars[bk])): continue
                    targets[(pre,dd)]=c
            e=None
        else:
            bx,by,bd=terms[b]; e=cell(bx,by); ed=D[bd]; e1=(e[0]+ed[0],e[1]+ed[1]); targets={(e1,(-ed[0],-ed[1])):e}
        allow={s,s1}|{k[0] for k in targets}
        if e: allow|={e}
        def free(c,d):
            if not(0<=c[0]<NX and 0<=c[1]<NY): return None
            if c in blocked and c not in allow: return None
            if c not in occ: return 0
            L=occ[c]
            if len(L)!=1: return None
            t=L[0][1]
            if t=='H' and d[0]==0: return 1
            if t=='V' and d[1]==0: return 1
            return None
        if free(s1,sd) is None: return None
        start=(s1,sd);dist={start:0};pq=[(0,s1,sd)];prev={start:None};found=None
        while pq:
            cst,c,d=heapq.heappop(pq)
            if dist.get((c,d),1e9)<cst: continue
            if (c,d) in targets and c not in occ: found=(c,d);break
            cross=c in occ
            for nd in DIRS:
                if nd==(-d[0],-d[1]): continue
                if cross and nd!=d: continue
                n=(c[0]+nd[0],c[1]+nd[1]); f=free(n,nd)
                if f is None: continue
                nc=cst+1+(4 if nd!=d else 0)+30*f
                if nc<dist.get((n,nd),1e9): dist[(n,nd)]=nc;prev[(n,nd)]=(c,d);heapq.heappush(pq,(nc,n,nd))
        if not found: return None
        path=[];k=found
        while k: path.append(k[0]);k=prev[k]
        full=[s]+path[::-1]+[targets[found]]
        mark(full,wid);res[wid]=full;total+=dist[found]
    return total,res,occ
random.seed(int(sys.argv[1]) if len(sys.argv)>1 else 1)
